head.script:
scwin.screenId = "jldfil25910";

///////// 1. 변수 및 선언 영역 /////////

scwin.ex = $c.util.getComponent('ex');

scwin.filebox = $c.util.getComponent('filebox');

scwin.modifiyDate = "N";

scwin.delck = "N";

///////// 2. 초기화 영역 /////////

// 화면 진입점 — 2구역 최상단 정의, init_* 순차 실행(래핑 없이 단일 정의)
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 순차 실행한다.
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신
        scwin.init_fillNow(); // 2) sysYear 미수신 시 서버 연도 충전
        scwin.init_attrReals(); // 3) textarea 라벨 동적 렌더
        scwin.init_rowCopies(); // 4) 기준년도·결산월 표시 행 복사
        scwin.init_conds(); // 5) 조건부 표시 영역 평가
        scwin.init_radio(); // 6) 배당기준일 라디오 초기 표시·change 바인딩
    } catch (ex) {
        $c.exception.handleError(ex, {
            context: "jldfil25910.onpageload"
        });
    }
};

// A. textarea 라벨 동적 렌더 (구 __attrReals IIFE)
/**
 * @method
 * @name init_attrReals
 * @description textarea(주주명부폐쇄·이익배당) 라벨을 조회값으로 동적 렌더한다.
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function() {
    const attrReals = [{
            childId: "txa_shrhdNmlistClsBasddContn",
            attr: "label",
            fn: function() {
                return String($c.data.readValue("dma_dividendDate", "shrhdNmlistClsBasddContn", {
                    silent: true
                }));
            }
        },
        {
            childId: "txa_proftDivRemk",
            attr: "label",
            fn: function() {
                return String($c.data.readValue("dma_dividendDate", "proftDivRemk", {
                    silent: true
                }));
            }
        }
    ];
    $c.util.applyAttrReals(attrReals);
};

// B. 기준년도·결산월 표시 행 복사 (구 __rowCopies IIFE)
/**
 * @method
 * @name init_rowCopies
 * @description 기준년도·결산월 표시 행을 조회값으로 채운다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopies = function() {
    const rowCopies = [{
            childId: "__rb2",
            fn: function() {
                return String($c.data.readValue("dma_dividendDate", "basYy", {
                    silent: true
                })) + " 년";
            }
        },
        {
            childId: "__rb3",
            fn: function() {
                return String($c.data.readValue("dma_dividendDate", "acntclsMm", {
                    silent: true
                })) + " 월";
            }
        }
    ];
    $c.data.copyRows(rowCopies);
};

// C. dma_pageContext.sysYear 서버 연도 충전 (구 __fillNow IIFE)
/**
 * @method
 * @name init_fillNow
 * @description dma_pageContext.sysYear 미수신 시 서버 연도로 충전한다.
 * @returns {void}
 * @hidden N
 */
scwin.init_fillNow = function() {
    const pc = $c.util.getComponent("dma_pageContext");
    if (pc && pc.set && !pc.get("sysYear")) {
        pc.set("sysYear", $c.date.getServerDateTime("yyyy"));
    }
};

// 화면 전환 파라미터 수신 (공용 $c.data.recvParamData, 이름 고정 "paramData")
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 recvParamData).
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function() {
    $c.data.recvParamData("dma_pageContext");
};

// D. 조건부 표시 영역 런타임 평가 (구 evalConds IIFE)
/**
 * @method
 * @name init_conds
 * @description 수정 가능 여부·상장구분·첨부 유무에 따른 조건부 표시 영역을 평가한다.
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function() {
    const modChk = function() {
        return $c.data.readValue("dma_pageContext", "checkModifiyDate", {
            ctx: true,
            label: "checkModifiyDate"
        });
    };
    const listStat = function() {
        return $c.data.readValue("dma_pageContext", "listStatCd", {
            ctx: true,
            label: "listStatCd"
        });
    };
    const isEditable = function() {
        return (modChk() === "Y" || modChk() === "U") && listStat() === "Y";
    };
    const isReadonly = function() {
        return modChk() === "N" || listStat() !== "Y";
    };
    const hasBzProcsNo = function() {
        return !$c.util.isEmpty($c.data.readValue("dma_dividendDate", "bzProcsNo", {
            label: "dividendDate.bzProcsNo"
        }));
    };
    const binds = [{
            id: "if_attachFileNm",
            fn: function() {
                return !$c.util.isEmpty($c.data.readValue("dma_dividendDate", "attachFileNm", {
                    label: "dividendDate.attachFileNm"
                }));
            }
        },
        {
            id: "if_checkModifiyDate",
            fn: isEditable
        },
        {
            id: "tr_63",
            fn: isEditable
        },
        {
            id: "tr_70",
            fn: isEditable
        },
        {
            id: "tr_73",
            fn: isEditable
        },
        {
            id: "tr_78",
            fn: isEditable
        },
        {
            id: "tr_83",
            fn: isEditable
        },
        {
            id: "if_checkModifiyDate_2",
            fn: isReadonly
        },
        {
            id: "tr_98",
            fn: isReadonly
        },
        {
            id: "tr_105",
            fn: isReadonly
        },
        {
            id: "tr_108",
            fn: isReadonly
        },
        {
            id: "tr_112",
            fn: isReadonly
        },
        {
            id: "tr_116",
            fn: isReadonly
        },
        {
            id: "registerBtn",
            fn: function() {
                return !hasBzProcsNo();
            }
        },
        {
            id: "registerBtn_2",
            fn: hasBzProcsNo
        }
    ];
    $c.util.evalConds(binds);
};

// E. 배당기준일 라디오 초기 표시 + change 바인딩 (구 화면 onpageload 본문)
/**
 * @method
 * @name init_radio
 * @description 배당기준일 라디오 초기 표시 상태와 change 이벤트를 바인딩한다.
 * @returns {void}
 * @hidden N
 */
scwin.init_radio = function() {
    scwin.basDRadio();
    $("input[name='divBasDdYn']").change(function() {
        const yn = this.value;
        if (yn === "Y") {
            $c.util.getComponent("cal_divBasDd").setValue("");
            $(".ui-datepicker-trigger").click();
        } else {
            $c.util.getComponent("cal_divBasDd").setValue("-");
        }
    });
};

// 업로드 컴포넌트 참조(파일 컨트롤)
scwin.upd_attachFile = (typeof __krxFileControl === "function") ? __krxFileControl("upd_attachFile") : scwin.resolveFileControlRoot().querySelector('[id="upd_attachFile"]');

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name dividendDateAttachForm_onsubmit
 * @description 첨부 폼 제출 — 기본 제출을 막는다(false 반환).
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.dividendDateAttachForm_onsubmit = function(e) {
    try {
        return false;
    } catch (ex) {
        $c.exception.handleError(ex, {
            context: "jldfil25910.dividendDateAttachForm_onsubmit"
        });
    }
};

/**
 * @method
 * @name dividendDateForm_onsubmit
 * @description 신고 폼 제출 — 기본 제출을 막는다(false 반환).
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.dividendDateForm_onsubmit = function(e) {
    try {
        return false;
    } catch (ex) {
        $c.exception.handleError(ex, {
            context: "jldfil25910.dividendDateForm_onsubmit"
        });
    }
};

/**
 * @method
 * @name txt_exTable_onmouseover
 * @description 입력 예시 안내 표를 표시한다.
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.txt_exTable_onmouseover = function(e) {
    try {
        scwin.onMover();
    } catch (ex) {
        $c.exception.handleError(ex, {
            context: "jldfil25910.txt_exTable_onmouseover"
        });
    }
};

/**
 * @method
 * @name txt_exTable_onmouseout
 * @description 입력 예시 안내 표를 숨긴다.
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.txt_exTable_onmouseout = function(e) {
    try {
        scwin.onMout();
    } catch (ex) {
        $c.exception.handleError(ex, {
            context: "jldfil25910.txt_exTable_onmouseout"
        });
    }
};

/**
 * @method
 * @name txa_shrhdNmlistClsBasddContn_onkeyup
 * @description 주주명부폐쇄 입력 바이트 수를 갱신한다.
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.txa_shrhdNmlistClsBasddContn_onkeyup = function(e) {
    try {
        const __self = (e && (e.element || e.target || e.srcElement)) || this;
        scwin.fn_setLength(__self.value, 'text1', '4000');
    } catch (ex) {
        $c.exception.handleError(ex, {
            context: "jldfil25910.txa_shrhdNmlistClsBasddContn_onkeyup"
        });
    }
};

/**
 * @method
 * @name txa_shrhdNmlistClsBasddContn_onblur
 * @description 주주명부폐쇄 입력 길이 초과를 검사한다.
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.txa_shrhdNmlistClsBasddContn_onblur = async function(e) {
    try {
        const __self = (e && (e.element || e.target || e.srcElement)) || this;
        await scwin.fn_estimateCounter(__self, '4000');
    } catch (ex) {
        await $c.exception.handleError(ex, {
            context: "jldfil25910.txa_shrhdNmlistClsBasddContn_onblur"
        });
    }
};

/**
 * @method
 * @name txa_proftDivRemk_onkeyup
 * @description 이익배당 입력 바이트 수를 갱신한다.
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.txa_proftDivRemk_onkeyup = function(e) {
    try {
        const __self = (e && (e.element || e.target || e.srcElement)) || this;
        scwin.fn_setLength(__self.value, 'text2', '4000');
    } catch (ex) {
        $c.exception.handleError(ex, {
            context: "jldfil25910.txa_proftDivRemk_onkeyup"
        });
    }
};

/**
 * @method
 * @name txa_proftDivRemk_onblur
 * @description 이익배당 입력 길이 초과를 검사한다.
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.txa_proftDivRemk_onblur = async function(e) {
    try {
        const __self = (e && (e.element || e.target || e.srcElement)) || this;
        await scwin.fn_estimateCounter(__self, '4000');
    } catch (ex) {
        await $c.exception.handleError(ex, {
            context: "jldfil25910.txa_proftDivRemk_onblur"
        });
    }
};

/**
 * @method
 * @name btn_FileDown_onclick
 * @description 첨부파일 다운로드를 실행한다(작성 영역).
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.btn_FileDown_onclick = async function(e) {
    try {
        await scwin.fn_FileDown('' + scwin.getDmaValue("dma_dividendDate", "bzProcsNo") + '', '' + scwin.getDmaValue("dma_dividendDate", "attachFileNm") + '');
    } catch (ex) {
        await $c.exception.handleError(ex, {
            context: "jldfil25910.btn_FileDown_onclick"
        });
    }
};

/**
 * @method
 * @name rd_divBasDdYn2_onclick
 * @description 읽기전용 라디오 클릭을 막는다(false 반환).
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.rd_divBasDdYn2_onclick = function(e) {
    try {
        return false;
    } catch (ex) {
        $c.exception.handleError(ex, {
            context: "jldfil25910.rd_divBasDdYn2_onclick"
        });
    }
};

/**
 * @method
 * @name btn_FileDown_2_onclick
 * @description 첨부파일 다운로드를 실행한다(조회 영역).
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.btn_FileDown_2_onclick = async function(e) {
    try {
        await scwin.fn_FileDown('' + scwin.getDmaValue("dma_dividendDate", "bzProcsNo") + '', '' + scwin.getDmaValue("dma_dividendDate", "attachFileNm") + '');
    } catch (ex) {
        await $c.exception.handleError(ex, {
            context: "jldfil25910.btn_FileDown_2_onclick"
        });
    }
};

/**
 * @method
 * @name btn_list_onclick
 * @description 목록 화면으로 이동한다.
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.btn_list_onclick = function(e) {
    try {
        scwin.fn_list();
    } catch (ex) {
        $c.exception.handleError(ex, {
            context: "jldfil25910.btn_list_onclick"
        });
    }
};

/**
 * @method
 * @name registerBtn_onclick
 * @description [저장] 버튼 클릭 — 등록 처리를 실행한다.
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.registerBtn_onclick = async function(e) {
    try {
        await scwin.fn_register();
    } catch (ex) {
        await $c.exception.handleError(ex, {
            context: "jldfil25910.registerBtn_onclick"
        });
    }
};

/**
 * @method
 * @name registerBtn_2_onclick
 * @description [수정] 버튼 클릭 — 등록 처리를 실행한다.
 * @param {Object} e
 * @returns {void}
 * @hidden N
 */
scwin.registerBtn_2_onclick = async function(e) {
    try {
        await scwin.fn_register();
    } catch (ex) {
        await $c.exception.handleError(ex, {
            context: "jldfil25910.registerBtn_2_onclick"
        });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name tx_fn_register
 * @description 배당기준일자 신고를 서버에 등록한다. 응답 실패 시 메시지를 알린다.
 * @returns {void}
 * @hidden N
 */
scwin.tx_fn_register = async function() {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "dividendBaseDate.do",
        ref: "dma_registerReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) {
            await $c.win.alert(res.responseJSON.message);
        }
    }
    return res;
};

/**
 * @method
 * @name tx_fn_FileDown
 * @description 첨부파일 다운로드 요청을 전송한다($c.data.downFile).
 * @returns {void}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function() {
    return await $c.data.downFile("filedown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {}));
};

/**
 * @method
 * @name tx_fn_modifiyDate
 * @description 배당기준일 수정 가능 여부를 서버에 조회한다. 응답 실패 시 메시지를 알린다.
 * @returns {void}
 * @hidden N
 */
scwin.tx_fn_modifiyDate = async function() {
    const sbmOptions = {
        id: "tx_fn_modifiyDate",
        method: "post",
        action: "dividendBaseDate.do",
        ref: "dma_modifiyDateReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) {
            await $c.win.alert(res.responseJSON.message);
        }
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name fn_list
 * @description 목록 화면(jldfil25900)으로 이동한다.
 * @returns {void}
 * @hidden N
 */
scwin.fn_list = function() {
    $('#dividendDateForm').append('<input type="hidden" name="method" id="method" />');
    $c.util.getComponent("dma_listReq").set("method", "dividendDateList");
    $('#dividendDateForm').attr("action", "dividendBaseDate.do");
    $('#dividendDateForm').attr("onsubmit", "");
    $c.win.moveUrl("/jldfil25900/jldfil25900.xml");
};

/**
 * @method
 * @name fn_register
 * @description 수정 가능 여부 확인·검증 후 등록을 실행한다.
 * @returns {void}
 * @hidden N
 */
scwin.fn_register = async function() {
    await scwin.fn_modifiyDate();
    if (await scwin.fn_validation()) {
        if (!await $c.win.confirm("저장하시겠습니까")) {
            return;
        }
        $('#dividendDateForm').append('<input type="hidden" name="method" id="method" />');
        $c.util.getComponent("dma_listReq").set("method", "dividendDateRegister");
        $('#dividendDateForm').attr("action", "dividendBaseDate.do");
        $('#dividendDateForm').attr("onsubmit", "");
        await scwin.tx_fn_register();
    }
};

/**
 * @method
 * @name fn_fileValidation
 * @description 첨부파일 확장자·용량 유효성을 검사한다.
 * @returns {void}
 * @hidden N
 */
scwin.fn_fileValidation = async function() {
    let file = $("input[type='file']");
    if (file.attr("value") !== "" && file.attr("value") != null) {
        if (scwin.fn_fileTypeChk(file.attr("value")) > 0) {
            await $c.win.alert('첨부할 수 없는 확장자를 가지 파일이 ' + '있습니다.\n사용가능 확장자 : DRT, bmp, gif, jpeg, jpg, png, hwp, docx, doc, xls, xlsx, ppt, pptx, pdf, zip, txt');
            return false;
        }
        if (scwin.fn_fileSizeChk($c.util.getComponent("upd_attachFile").files[0].size) > 0) {
            await $c.win.alert('첨부파일의 용량은 개당 20MB를 넘을수 없습니다.');
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name fn_fileTypeChk
 * @description 파일 확장자가 허용 목록에 없으면 1을 반환한다.
 * @param {Object} val
 * @returns {void}
 * @hidden N
 */
scwin.fn_fileTypeChk = function(val) {
    let isFileType = new Array("drt", "bmp", "gif", "jpeg", "jpg", "png", "hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "zip", "txt");
    let fileType = val.substring(val.lastIndexOf(".") + 1).toLowerCase();
    let returnVal = 0;
    let typeChkCnt = 0;
    for (let i = 0; i < isFileType.length; i++) {
        if (isFileType[i] === fileType) {
            typeChkCnt++;
        }
    }
    if (typeChkCnt === 0) {
        returnVal = 1;
    }
    return returnVal;
};

/**
 * @method
 * @name fn_fileSizeChk
 * @description 파일 용량이 20MB 를 초과하면 1을 반환한다.
 * @param {Object} fileSize
 * @returns {void}
 * @hidden N
 */
scwin.fn_fileSizeChk = function(fileSize) {
    if (fileSize > (1024 * 1024 * 20)) {
        return 1;
    }
    return 0;
};

/**
 * @method
 * @name fn_validation
 * @description 배당기준일·주주명부·이익배당·첨부 등 등록 전 필수 항목을 검증한다.
 * @returns {void}
 * @hidden N
 */
scwin.fn_validation = async function() {
    if (scwin.modifiyDate === "N") {
        await $c.win.alert("제출 시간을 초과했습니다.");
        return false;
    }
    if (($c.util.getComponent('cal_divBasDd').getValue() == null ? '' : String($c.util.getComponent('cal_divBasDd').getValue())) === '') {
        await $c.win.alert("배당기준일을 등록해주세요.");
        return false;
    }
    if (($c.util.getComponent('txa_shrhdNmlistClsBasddContn').getValue() == null ? '' : String($c.util.getComponent('txa_shrhdNmlistClsBasddContn').getValue())) === '') {
        await $c.win.alert("주주명부의 폐쇄 및 기준일을 등록해주세요.");
        return false;
    }
    if (($c.util.getComponent('txa_proftDivRemk').getValue() == null ? '' : String($c.util.getComponent('txa_proftDivRemk').getValue())) === '') {
        await $c.win.alert("이익배당을 등록해주세요.");
        return false;
    }
    if (($c.util.getComponent('upd_attachFile').getValue() == null ? '' : String($c.util.getComponent('upd_attachFile').getValue())) === '') {
        if (($c.util.getComponent('ipt_bzProcsNo').getValue() == null ? '' : String($c.util.getComponent('ipt_bzProcsNo').getValue())) === '') {
            await $c.win.alert("첨부파일을 등록해주세요.");
            return false;
        } else {
            if (scwin.delck === "Y") {
                await $c.win.alert("첨부파일을 등록해주세요.");
                return false;
            }
        }
    }
    if (!await scwin.fn_fileValidation()) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name fn_fileDel
 * @description 첨부파일을 삭제한다(확인 후).
 * @param {Object} ipt_attachFileNm
