scwin.fn_fileDel = async function(ipt_attachFileNm) {
    let msg = ipt_attachFileNm + " 첨부파일을 삭제하시겠습니까?\n삭제된 파일은 복구가 불가능합니다.";
    if (!await $c.win.confirm(msg)) {
        return;
    }
    scwin.filebox.setStyle("display", "");
