};

/**
 * @method
 * @name fn_setLength
 * @description 입력 바이트 수를 계산해 카운터 표시에 반영한다.
 * @param {Object} obj
 * @param {Object} tdName
 * @param {Object} maxLength
 * @returns {void}
 * @hidden N
 */
scwin.fn_setLength = function(obj, tdName, maxLength) {
    let strLength = scwin.fn_calBytes(obj);
    scwin.setComponentText($c.util.getComponent(tdName), "(" + strLength + "/" + maxLength + ")", tdName);
};

/**
 * @method
 * @name fn_estimateCounter
 * @description 입력 길이가 최대치를 초과하면 알림 후 선택 상태로 되돌린다.
 * @param {Object} obj
 * @param {Object} maxLength
 * @returns {void}
 * @hidden N
 */
scwin.fn_estimateCounter = async function(obj, maxLength) {
    if (scwin.fn_calBytes(obj.value) > maxLength) {
        await $c.win.alert('한글 2000자 이하, 숫자/영문 4000자 이하까지만 입력이 가능합니다.');
        obj.select();
        return;
    }
};

/**
 * @method
 * @name fn_calBytes
 * @description 문자열의 바이트 길이를 계산한다(한글 2·개행 2·그 외 1).
 * @param {Object} str
 * @returns {void}
 * @hidden N
 */
scwin.fn_calBytes = function(str) {
    let tcount = 0;
    let tmpStr = new String(str);
    let temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};

/**
 * @method
 * @name fn_FileDown
 * @description 첨부파일 다운로드 폼을 구성해 전송한다.
 * @param {Object} ipt_contnId
 * @param {Object} ipt_attachFileNm
 * @returns {void}
 * @hidden N
 */
scwin.fn_FileDown = async function(ipt_contnId, ipt_attachFileNm) {
    let frm = (document.DividendDateAttachForm || {
        elements: []
    });
    $('#dividendDateAttachForm').append('<input type="hidden" name="method" id="method" />');
    $('#dividendDateAttachForm').attr("action", "dividendDateFiledown.do");
    $c.util.getComponent("dma_listReq").set("method", "dividendDateAttachFile");
    $('#dividendDateAttachForm').attr("onsubmit", "");
    $c.util.getComponent('ipt_contnId').setValue(ipt_contnId);
    $c.util.getComponent('ipt_attachFileNm').setValue(ipt_attachFileNm);
    await scwin.tx_fn_FileDown();
    $("#method").remove();
};

