// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name fn_modifiyDate
 * @description 수정 가능 여부 조회 후 결과를 scwin.result/modifiyDate 에 반영한다.
 * @returns {void}
 * @hidden N
 */
scwin.fn_modifiyDate = async function() {
    const res = await scwin.tx_fn_modifiyDate();
    const body = (res && res.responseJSON && (res.responseJSON.body != null ? res.responseJSON.body : res.responseJSON)) || {};
    scwin.result = body;
    scwin.modifiyDate = scwin.result.checkModifiyDate;
    return res;
};

// (헬퍼) DataMap 값 안전 추출 — 인라인 IIFE 대체
scwin.getDmaValue = function(dmaId, key) {
    try {
        const d = $c.util.getComponent(dmaId);
        if (!d) {
            return "";
        }
        let v;
        if (typeof d.get === "function") {
            v = d.get(key);
        }
        if ((v === undefined || v === null || v === "") && typeof d.getCellData === "function") {
            v = d.getCellData(0, key);
        }
        return (v === undefined || v === null) ? "" : v;
    } catch (e) {
        return "";
    }
};

// (헬퍼) 컴포넌트 값 쓰기(setValue/setText) — 인라인 IIFE 대체
scwin.setComponentText = function(comp, val, label) {
    if (comp && comp.setValue) {
        comp.setValue(val);
    } else if (comp && comp.setText) {
        comp.setText(val);
    } else {
        console.warn("[sdd] 값 쓰기 미지원 컴포넌트: " + label);
    }
};

// (헬퍼) 파일 컨트롤 루트 노드 확보 — 인라인 IIFE 대체
scwin.resolveFileControlRoot = function() {
    try {
        const f = (typeof $c !== "undefined" && $c.win && $c.win.getFrame) ? $c.win.getFrame() : null;
        return (f && f.render) ? f.render : document;
    } catch (e) {
        return document;
    }
};
